import json, time, urllib.request

BASE = "http://127.0.0.1:1933"
HDR = {"Authorization": "Bearer magpie", "Content-Type": "application/json"}

SESSIONS = [
    "dsh-4c686b4f-9cc2-467d-a294-11185c86b5ee",
    "dsh-session-6340e208-3870-4ad9-8e1f-caaf297863c9",
    "dsh-session-43e97aa4-9359-48f3-b205-0a72f71081a7",
]
AID = "archive_001"

def get(url):
    req = urllib.request.Request(url, headers=HDR)
    with urllib.request.urlopen(req, timeout=120) as r:
        return json.loads(r.read().decode())

def post(url, body):
    data = json.dumps(body).encode()
    req = urllib.request.Request(url, data=data, headers=HDR, method="POST")
    try:
        with urllib.request.urlopen(req, timeout=120) as r:
            return r.status, json.loads(r.read().decode())
    except urllib.error.HTTPError as e:
        return e.code, e.read().decode()

for sid in SESSIONS:
    arc = get(f"{BASE}/api/v1/sessions/{sid}/archives/{AID}")
    sha = arc.get("messages_sha256") or arc.get("expected_messages_sha256")
    st = arc.get("status")
    print(sid, "archive_status", st, "sha", sha)
    if not sha:
        print("  skip: no sha")
        continue
    code, resp = post(f"{BASE}/api/v1/sessions/{sid}/archives/{AID}/retry", {"expected_messages_sha256": sha})
    print("  retry", code, resp if isinstance(resp, str) else json.dumps(resp, ensure_ascii=False)[:500])
    time.sleep(2)

